// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function testFuzz_property(uint256 val) public {
        // SetMinSum is only callable before initialization; any uint value is admissible.
        address actor = address(0xA11CE);
        vm.prank(actor);
        c.SetMinSum(val);

        // General rule: after SetMinSum(_val), the stored MinSum equals exactly _val.
        assertTrue(c.MinSum() == val);
    }
}
